window.FULL_ARISTOTELE=[
{
"id":"a1","n":"A1","who":"aristotele","title":"Stagira, Accademia e Liceo","subtitle":"La biografia intellettuale e la costruzione di una comunità di ricerca","problem":"Come può un filosofo diventare profondamente originale senza cancellare i vent’anni trascorsi nella scuola del proprio maestro?",
"sections":[
{"h":"Uno straniero nel centro della filosofia greca","p":["Aristotele nasce nel 384 a.C. a Stagira, città della penisola calcidica legata al regno macedone. Il padre Nicomaco appartiene alla tradizione medica e viene associato alla corte di Aminta III. È prudente non trasformare questo dato biografico in una spiegazione automatica dell’interesse aristotelico per la natura; tuttavia il contesto familiare rende plausibile una precoce familiarità con pratiche di osservazione e classificazione.","Intorno ai diciassette anni Aristotele si trasferisce ad Atene ed entra nell’Accademia di Platone. Vi rimane circa vent’anni, dal 367 al 347 a.C. Non è quindi un avversario esterno del platonismo: si forma nel luogo in cui matematica, dialettica, politica e ricerca dei principi vengono intrecciate. La successiva critica delle Idee nasce dall’interno di quella problematica e conserva l’esigenza platonica di rendere intelligibile il reale."],"box":{"type":"focusBox","title":"Continuità e critica","text":"Aristotele non sostituisce semplicemente le idee con i fatti. Mantiene la ricerca delle forme, delle cause e dell’universale, ma rifiuta che il principio intelligibile sia separato dalle cose concrete."}},
{"h":"Dopo Platone: Asso, Lesbo e la ricerca naturale","p":["Alla morte di Platone Aristotele lascia Atene. Si reca ad Asso, nell’area governata da Ermia di Atarneo, e poi a Mitilene, sull’isola di Lesbo. In questi anni collabora con Teofrasto e svolge ricerche sugli esseri viventi e sugli ambienti marini. Le opere biologiche testimoniano una straordinaria quantità di osservazioni, anche se non corrispondono al metodo sperimentale moderno.","Lo studio degli animali non è separato dalla filosofia. Classificare parti, funzioni, riproduzione e modi di vita significa cercare forma, causa e fine negli enti naturali. Aristotele non accumula dati come un archivista neutrale: li ordina attraverso domande teoriche. Allo stesso tempo, i fenomeni costringono la teoria a rispettare differenze e irregolarità che un sistema troppo astratto rischierebbe di cancellare."],"sub":[{"h":"Teofrasto","p":["Teofrasto diventerà il successore di Aristotele alla guida del Liceo e autore di importanti opere botaniche. La collaborazione ricorda che la produzione aristotelica è inserita in una scuola e in programmi collettivi di ricerca, non soltanto nell’attività isolata di un genio."]}]},
{"h":"Aristotele e Alessandro","p":["Intorno al 343 o 342 a.C. Filippo II chiama Aristotele in Macedonia per partecipare all’educazione del giovane Alessandro. La natura precisa del rapporto e l’influenza filosofica sul futuro conquistatore sono difficili da ricostruire. La tradizione ha amplificato il ruolo del maestro e il racconto secondo cui Alessandro avrebbe inviato campioni naturali dalle spedizioni non è documentato con sicurezza.","Il rapporto con la Macedonia avrà comunque conseguenze politiche. Quando Alessandro muore nel 323 a.C., ad Atene cresce la reazione antimacedone. Aristotele viene accusato di empietà e lascia la città. La frase secondo cui non avrebbe voluto permettere agli Ateniesi di peccare una seconda volta contro la filosofia è una tradizione successiva e va trattata con cautela, ma esprime il confronto inevitabile con la morte di Socrate."],"box":{"type":"criticalBox","title":"Biografia e leggenda","text":"Nelle vite dei filosofi antichi fatti, aneddoti e costruzioni esemplari si mescolano. La PWA distingue ciò che è storicamente ben attestato da ciò che appartiene alla tradizione."}},
{"h":"La fondazione del Liceo","p":["Nel 335 a.C. Aristotele torna ad Atene e fonda la propria scuola presso il santuario di Apollo Licio. Il termine peripatetici viene collegato al peripatos, il luogo coperto o il passeggio in cui si discuteva. L’immagine dei filosofi che insegnano camminando è plausibile, ma non esaurisce l’organizzazione della scuola.","Il Liceo appare come una comunità di ricerca ampia: raccoglie costituzioni, studia animali e piante, ordina problemi filosofici, analizza poesia e retorica. La tradizione attribuisce alla scuola la raccolta di 158 costituzioni; ci è pervenuta la Costituzione degli Ateniesi, la cui appartenenza al corpus aristotelico è generalmente accettata come prodotto della scuola. Il sapere viene costruito confrontando casi, predecessori e discipline."],"table":{"head":["Accademia","Liceo"],"rows":[["Fondata da Platone","Fondata da Aristotele"],["Centralità di matematica e dialettica","Programma enciclopedico e raccolta di dati"],["Ricerca di principi intelligibili separati","Ricerca di forme e cause nelle realtà concrete"],["Comunità filosofica e politica","Comunità filosofica e scientifica"]]}},
{"h":"La forma delle opere","p":["Aristotele compose probabilmente dialoghi e opere destinate a un pubblico ampio, molto apprezzate nell’antichità, ma quasi interamente perdute. I testi conservati hanno spesso uno stile denso, schematico, con riprese e tensioni interne. Sono tradizionalmente considerati scritti scolastici, appunti o materiali legati all’insegnamento.","La distinzione terminologica richiede precisione. Gli scritti destinati a un pubblico esterno vengono normalmente chiamati essoterici; quelli per l’attività interna, acroamatici o esoterici. Il corpus fu ordinato in età ellenistica e soprattutto associato all’edizione di Andronico di Rodi nel I secolo a.C., anche se la storia della trasmissione è più complessa di un singolo atto editoriale."],"sub":[{"h":"Perché la Metafisica si chiama così","p":["Il titolo non indica necessariamente una disciplina che Aristotele chiamasse metafisica. Deriva dalla collocazione dei libri dopo quelli di fisica, ta meta ta physika. Il contenuto riguarda la filosofia prima, l’essere in quanto essere, la sostanza e i principi supremi."]}]},
{"h":"Un sistema o una ricerca aperta?","p":["La vastità del corpus invita a rappresentare Aristotele come autore di un sistema perfettamente chiuso. In realtà le opere mostrano problemi, alternative, sviluppi e talvolta formulazioni non facilmente conciliabili. La filosofia prima, la teoria dell’anima, l’etica e la politica non sono capitoli dedotti da un’unica formula; ciascun campo possiede oggetti e metodi propri.","L’unità si trova soprattutto nello stile di ricerca: partire dai fenomeni e dalle opinioni autorevoli, formulare difficoltà, distinguere significati, cercare cause e salvare quanto più possibile delle evidenze. Aristotele costruisce un’architettura del sapere, ma resta attento alla specificità di ciò che studia."],"box":{"type":"worksBox","title":"Testi da collegare","text":"Metafisica I per il confronto con i predecessori; Parti degli animali e Storia degli animali per la ricerca biologica; Etica Nicomachea e Politica per la vita umana; Costituzione degli Ateniesi per il programma storico-politico."}}
],
"summary":["Aristotele si forma per circa vent’anni nell’Accademia e sviluppa la propria filosofia dall’interno dei problemi platonici.","Le ricerche di Asso e Lesbo mostrano l’integrazione tra osservazione e teoria.","Il rapporto con Alessandro e la Macedonia colloca il filosofo nelle tensioni politiche del IV secolo a.C.","Il Liceo è una comunità enciclopedica di ricerca e raccolta di dati.","Gran parte degli scritti conservati deriva dall’attività scolastica; le opere letterarie sono quasi tutte perdute.","L’unità aristotelica risiede più in un metodo di problematizzazione che in un sistema privo di tensioni."],
"questions":["In che senso Aristotele è insieme continuatore e critico di Platone?","Quanto possiamo spiegare una filosofia attraverso la biografia?","Quali vantaggi offre una comunità di ricerca rispetto al lavoro individuale?","Perché la forma incompleta o scolastica delle opere rende difficile interpretare Aristotele?"]
},
{
"id":"a2","n":"A2","who":"aristotele","title":"Metodo e classificazione delle scienze","subtitle":"Fenomeni, endoxa e differenti gradi di precisione","problem":"È ragionevole cercare in etica, biologia e matematica lo stesso tipo di prova e la stessa esattezza?",
"sections":[
{"h":"Partire da ciò che appare","p":["Aristotele non comincia normalmente cancellando il sapere precedente. Raccoglie i fenomeni, phainomena, e le endoxa, le opinioni condivise da tutti, dalla maggioranza o dai sapienti. Questi punti di partenza non sono infallibili. Vengono confrontati, messi in tensione e corretti.","Il metodo è spesso descritto come dialettico: si formulano le aporie, cioè le difficoltà, e si cerca una soluzione capace di conservare le intuizioni più solide. Nell’Etica Nicomachea, per esempio, le diverse idee di felicità non vengono semplicemente ignorate; rivelano aspetti del bene umano che devono essere ordinati. Nella Fisica le teorie dei predecessori sul movimento vengono esaminate perché ogni errore può contenere una parte di verità."],"box":{"type":"focusBox","title":"Salvare i fenomeni","text":"Una buona teoria non deve soltanto essere elegante. Deve spiegare perché le esperienze e le opinioni più autorevoli apparivano plausibili, distinguendo ciò che contengono di vero dagli errori."}},
{"h":"Induzione e universale","p":["La conoscenza comincia dalla percezione. Percezioni ripetute producono memoria; molte memorie formano esperienza; dall’esperienza l’intelletto può cogliere un universale. Questo movimento viene collegato all’induzione, epagoge. Non è una semplice somma numerica di casi, ma il riconoscimento di una struttura comune.","L’universale non è ricevuto già formulato dai sensi. I sensi incontrano individui: questo uomo, questa pianta. L’intelletto coglie la forma che può essere predicata di molti. In questo senso Aristotele non è un empirista ingenuo. L’esperienza fornisce il materiale e il controllo, ma la scienza richiede forme, definizioni e cause." ]},
{"h":"Dimostrare significa conoscere il perché","p":["Negli Analitici secondi la scienza, episteme, è conoscenza dimostrativa. Una dimostrazione è un sillogismo le cui premesse sono vere, prime, immediate e causali rispetto alla conclusione. Sapere che un fatto accade non equivale a sapere perché accade.","La distinzione tra dimostrazione del fatto e dimostrazione della causa è fondamentale. Una correlazione può permettere di riconoscere un fenomeno, ma la scienza cerca il termine medio che esprime la spiegazione. La logica è quindi collegata all’ontologia: una buona dimostrazione non deve soltanto essere formalmente valida, ma rappresentare il nesso reale."],"sub":[{"h":"Da dove vengono i principi?","p":["I principi primi non possono essere dimostrati da principi precedenti all’infinito. Aristotele attribuisce all’intelletto, nous, la capacità di coglierli attraverso l’esperienza e l’induzione. Scienza e intelletto sono perciò differenti ma complementari."]}]},
{"h":"La classificazione dei saperi","p":["Aristotele distingue scienze teoretiche, pratiche e produttive. Le teoretiche cercano la verità per se stessa: fisica, matematica e filosofia prima. Le pratiche orientano l’azione: etica e politica. Le produttive guidano la fabbricazione di un’opera: arti e tecniche.","La distinzione dipende dall’oggetto e dal fine. La fisica studia enti separabili ma mobili; la matematica considera strutture astratte dal movimento; la filosofia prima studia l’essere in quanto essere e, in una sua direzione, la sostanza immobile. L’etica non produce un oggetto esterno e non si limita a contemplare: mira a vivere bene."],"table":{"head":["Tipo di scienza","Fine","Esempi"],"rows":[["Teoretica","Conoscere il vero","Fisica, matematica, filosofia prima"],["Pratica","Agire bene","Etica, politica"],["Produttiva","Produrre un’opera","Poetica, retorica, tecniche"]]}},
{"h":"Il grado di precisione dipende dall’oggetto","p":["All’inizio dell’Etica Nicomachea Aristotele avverte che una persona colta cerca in ciascun campo il grado di precisione consentito dalla materia. Le azioni umane sono variabili, dipendono da circostanze e non possono essere trattate come figure geometriche.","Questa tesi non autorizza l’arbitrio. L’etica argomenta, distingue, definisce fini e virtù, ma le sue conclusioni valgono per lo più. La saggezza pratica deve giudicare il caso concreto. Pretendere una regola matematica può essere una forma di irrazionalità, perché ignora la natura contingente dell’azione."],"box":{"type":"criticalBox","title":"Aristotele e il metodo sperimentale","text":"Aristotele attribuisce grande valore all’osservazione, soprattutto in biologia, ma non possiede il metodo sperimentale quantitativo moderno. Chiamarlo padre dell’empirismo è una formula divulgativa da usare con cautela."}},
{"h":"La specializzazione senza frammentazione","p":["Ogni scienza possiede principi propri e non può dimostrare tutto attraverso un’unica disciplina. La geometria non dimostra direttamente fatti biologici; la fisica non stabilisce da sola il bene umano. Questa autonomia protegge la specificità degli oggetti.","Nello stesso tempo, i saperi non sono isolati. La logica fornisce strumenti comuni; la filosofia prima studia concetti come essere, sostanza e causa; etica e politica sono collegate perché la vita buona richiede istituzioni. L’enciclopedia aristotelica è un ordine di differenze e relazioni, non una riduzione di tutto a un metodo unico."],"box":{"type":"worksBox","title":"Testi da collegare","text":"Analitici secondi per scienza e principi; Topici per dialettica ed endoxa; Metafisica I per la storia delle cause; Etica Nicomachea I per precisione e fine; Parti degli animali I per il metodo biologico."}}
],
"summary":["La ricerca aristotelica parte da fenomeni, endoxa e aporie.","L’induzione conduce dall’esperienza al riconoscimento dell’universale.","La dimostrazione scientifica deve esprimere una causa, non soltanto una validità formale.","I principi sono colti dall’intelletto e non dimostrati all’infinito.","Scienze teoretiche, pratiche e produttive si distinguono per oggetto e fine.","Il grado di precisione deve essere adeguato alla natura della materia studiata."],
"questions":["Perché le opinioni comuni possono essere un punto di partenza senza essere un criterio finale?","Che differenza c’è tra osservare molti casi e cogliere un universale?","Una spiegazione scientifica coincide con una previsione corretta?","Perché l’etica non può avere la precisione della geometria?","La specializzazione delle scienze favorisce o ostacola una visione unitaria?"]
},
{
"id":"a3","n":"A3","who":"aristotele","title":"La logica","subtitle":"Termini, proposizioni, sillogismi e dimostrazione scientifica","problem":"Come possiamo distinguere un ragionamento che persuade da uno in cui la conclusione segue realmente dalle premesse?",
"sections":[
{"h":"La logica come strumento","p":["La raccolta degli scritti logici viene chiamata Organon, strumento. Il titolo è posteriore, ma esprime bene la funzione attribuita alla logica: non una scienza particolare dello stesso tipo della fisica, bensì l’analisi delle forme attraverso cui ogni sapere argomenta.","Aristotele non usa il termine logica nel senso disciplinare moderno. Parla di analitica quando scompone il ragionamento e di dialettica quando studia inferenze basate su opinioni probabili. Il suo lavoro costruisce per la prima volta una teoria sistematica della deduzione."],"box":{"type":"focusBox","title":"Forma e contenuto","text":"Un ragionamento può essere formalmente valido anche se parte da premesse false. La verità della conclusione scientifica richiede sia una forma valida sia premesse vere e appropriate."}},
{"h":"Termini e proposizioni","p":["Un termine come uomo o mortale non è da solo vero o falso. La verità compare quando si uniscono o separano termini in una proposizione: ogni uomo è mortale. Le proposizioni possono essere universali o particolari, affermative o negative.","Aristotele analizza anche il rapporto tra linguaggio, pensiero e realtà. Le parole vocali simboleggiano affezioni dell’anima, che a loro volta si riferiscono alle cose. Le lingue differiscono, mentre le realtà e le strutture mentali cui rinviano sono comuni. Questa concezione evita di identificare direttamente parola e oggetto." ]},
{"h":"Le categorie","p":["Le Categorie presentano dieci modi fondamentali di predicazione: sostanza, quantità, qualità, relazione, luogo, tempo, posizione, avere, agire e patire. Dire Socrate, alto, padre, ad Atene o seduto significa predicare secondo modi differenti.","La sostanza occupa una posizione speciale. Socrate può essere soggetto di predicati, mentre il bianco esiste in una sostanza. La classificazione è insieme logica e ontologica: riguarda ciò che diciamo dell’essere e i modi in cui gli enti sono."],"table":{"head":["Esempio","Categoria"],"rows":[["Socrate","Sostanza"],["Due cubiti","Quantità"],["Bianco","Qualità"],["Doppio","Relazione"],["Nel Liceo","Luogo"],["Ieri","Tempo"],["Seduto","Posizione"],["Armato","Avere"],["Tagliare","Agire"],["Essere tagliato","Patire"]]}},
{"h":"Il sillogismo","p":["Il sillogismo è un discorso in cui, poste alcune cose, qualcosa di diverso segue necessariamente per il fatto che esse sono state poste. Nel sillogismo categorico due premesse collegano tre termini: maggiore, minore e medio. Il termine medio compare nelle premesse ma non nella conclusione.","Nell’esempio ogni animale è mortale; ogni uomo è animale; dunque ogni uomo è mortale, animale è il termine medio. La necessità dipende dalla forma. Se si afferma ogni gatto è animale; ogni cane è animale; dunque ogni cane è gatto, le premesse possono essere vere ma la conclusione non segue: il termine medio non connette le classi nel modo richiesto."],"sub":[{"h":"Figure e modi","p":["Aristotele classifica le disposizioni del termine medio e le combinazioni di proposizioni valide. I nomi Barbara, Celarent e simili sono invenzioni medievali per memorizzare i modi, non termini usati da Aristotele."]}]},
{"h":"Validità, verità e scienza","p":["La logica formale stabilisce se la conclusione segue. La scienza richiede di più. Negli Analitici secondi la dimostrazione parte da premesse vere, prime, immediate, anteriori e causali. Una deduzione da premesse vere può mostrare che un fatto è così senza mostrarne il perché.","Il termine medio di una dimostrazione scientifica deve esprimere la causa. La logica non è quindi separata dalla realtà. La forma valida garantisce il passaggio; la struttura causale delle cose garantisce che il ragionamento sia conoscenza e non semplice coerenza."],"box":{"type":"criticalBox","title":"Il limite della logica aristotelica","text":"La sillogistica analizza soprattutto relazioni tra classi e predicati. La logica moderna ha sviluppato strumenti più potenti per relazioni, quantificatori multipli e matematica, ma non rende irrilevante l’analisi aristotelica dell’argomentazione."}},
{"h":"Dialettica e fallacie","p":["Nei Topici Aristotele studia ragionamenti che partono da endoxa e sono utili nella discussione, nella ricerca e nell’esame dei principi. La dialettica non possiede la necessità della dimostrazione, ma consente di mettere alla prova una tesi da prospettive diverse.","Negli Elenchi sofistici analizza argomenti che sembrano confutazioni senza esserlo. Ambiguità, confusione tra senso assoluto e relativo, conclusioni che non seguono e domande complesse possono ingannare. Studiare le fallacie non serve soltanto a vincere dibattiti, ma a proteggere la ricerca dall’apparenza del ragionamento."],"box":{"type":"worksBox","title":"Testi da collegare","text":"Categorie per predicazione e sostanza; De interpretatione per proposizione e verità; Analitici primi per sillogismo; Analitici secondi per dimostrazione; Topici ed Elenchi sofistici per dialettica e fallacie."}},
{"h":"Eredità e uso contemporaneo","p":["La logica aristotelica ha dominato l’insegnamento per molti secoli ed è stata sviluppata da commentatori greci, arabi e latini. Il suo valore storico non consiste solo nell’avere fornito schemi validi, ma nell’aver separato la domanda sulla forma dell’inferenza dalla forza retorica di un discorso.","Nella vita quotidiana molte argomentazioni non sono sillogismi completi; contengono premesse implicite e probabilità. Tuttavia le distinzioni tra validità, verità, causa e persuasione rimangono fondamentali per leggere notizie, valutare prove e discutere responsabilmente." ]}
],
"summary":["La logica analizza le forme del ragionamento ed è tradizionalmente chiamata Organon.","Termini non sono veri o falsi; le proposizioni possono esserlo.","Le categorie classificano modi fondamentali di predicare e di essere.","Nel sillogismo la conclusione segue necessariamente attraverso il termine medio.","La validità formale non basta alla scienza: servono premesse vere e causali.","Dialettica e studio delle fallacie proteggono la ricerca dalle apparenze argomentative."],
"questions":["Un ragionamento valido può condurre a una conclusione falsa?","Che cosa aggiunge una spiegazione causale a una deduzione corretta?","Perché le categorie sono insieme linguistiche e ontologiche?","Quali fallacie ricorrono maggiormente nel dibattito pubblico contemporaneo?","La logica serve soltanto alle scienze?"]
},
{
"id":"a4","n":"A4","who":"aristotele","title":"Sostanza, materia e forma","subtitle":"L’essere primario e l’essenza immanente alle cose","problem":"Che cosa rende un individuo proprio quella cosa, pur attraverso mutamenti di materia, qualità e condizioni?",
"sections":[
{"h":"L’essere si dice in molti modi","p":["La filosofia prima studia l’essere in quanto essere, ma Aristotele rifiuta l’idea che essere sia un genere unico predicato nello stesso modo di tutto. Essere si dice in molti modi: come sostanza, qualità, quantità, relazione, potenza e atto. Questi significati sono però ordinati rispetto alla sostanza.","La sostanza è primaria perché gli altri modi esistono in una sostanza o vengono predicati di essa. Il bianco, il grande e il seduto non esistono separatamente come individui: sono determinazioni di qualcosa che è bianco, grande o seduto."],"box":{"type":"focusBox","title":"La domanda ontologica","text":"Aristotele cerca ciò che esiste primariamente e rende possibile attribuire proprietà, spiegare mutamenti e formulare definizioni."}},
{"h":"Sostanze prime e seconde","p":["Nelle Categorie le sostanze prime sono individui concreti, come questo uomo o questo cavallo. Le specie e i generi, uomo e animale, sono dette sostanze seconde perché esprimono che cosa è l’individuo e possono essere predicate di molti.","La priorità dell’individuo distingue Aristotele da una lettura semplice del platonismo. Non incontriamo l’Uomo in sé separato, ma individui che possiedono una forma comune. L’universale è conoscibile e necessario alla scienza, ma non esiste come sostanza separata nello stesso modo dell’individuo." ]},
{"h":"Materia e forma","p":["Per spiegare le sostanze sensibili Aristotele distingue materia e forma. La materia è ciò di cui una cosa è costituita e ciò che può ricevere determinazioni; la forma è la struttura, organizzazione ed essenza per cui quella materia è una certa cosa.","Una statua è bronzo e configurazione; un organismo è composto di materiali, ma vive perché essi sono organizzati secondo funzioni. Materia e forma non sono normalmente due oggetti affiancati. Sono principi inseparabili dell’ente concreto. La dottrina viene chiamata ilemorfismo, da hyle, materia, e morphe, forma."],"sub":[{"h":"Materia relativa","p":["Ciò che è forma a un livello può funzionare come materia a un altro. I mattoni sono materia della casa, ma possiedono già una forma. La materia pura, completamente priva di determinazione, non è un oggetto percepibile."]}]},
{"h":"Essenza e definizione","p":["La forma è strettamente legata al ti en einai, spesso tradotto essenza o ciò che era essere. Una definizione scientifica non elenca caratteristiche accidentali, ma esprime che cosa una cosa è. Dire che un uomo è abbronzato non definisce l’uomo; dire animale razionale cerca la struttura essenziale.","Le definizioni riguardano principalmente specie e forme. L’individuo contiene materia particolare e non è interamente esaurito da una definizione universale. La scienza conosce l’universale, pur partendo dagli individui concreti."],"box":{"type":"criticalBox","title":"Forma non significa sagoma","text":"La forma aristotelica non è soltanto il contorno visibile. È il principio organizzativo e funzionale che rende un ente ciò che è, soprattutto negli organismi viventi."}},
{"h":"Soggetto e mutamento","p":["Nel mutamento una cosa acquisisce o perde una determinazione. Quando una persona diventa istruita, il soggetto permane mentre cambia una qualità. Nella generazione sostanziale, come quando materiali diventano un organismo, la trasformazione è più radicale e richiede materia come sostrato potenziale.","La distinzione tra sostanza e accidenti permette di spiegare identità e cambiamento. Una sostanza può cambiare luogo, colore o dimensione restando la stessa. Non ogni proprietà appartiene all’essenza. La difficoltà consiste nel determinare quali cambiamenti conservino la sostanza e quali ne costituiscano la generazione o corruzione." ]},
{"h":"La Metafisica e il primato della forma","p":["Nei libri centrali della Metafisica Aristotele esamina candidati alla sostanza: materia, composto e forma. L’individuo concreto è composto, ma la forma appare primaria per definizione, conoscibilità e causalità. Essa spiega perché la materia costituisca proprio quell’ente.","Questo primato non reintroduce semplicemente una Forma platonica separata. La forma è nella sostanza sensibile. Tuttavia in alcuni casi, come il primo motore e il problema dell’intelletto, Aristotele ammette realtà non materiali, mostrando che il suo immanentismo non equivale a materialismo."],"table":{"head":["Principio","Domanda cui risponde"],"rows":[["Materia","Di che cosa è fatto?"],["Forma","Che cos’è e come è organizzato?"],["Composto","Qual è l’individuo concreto?"],["Accidente","Quale proprietà può cambiare senza distruggere l’ente?"]]}},
{"h":"Confronto con Platone","p":["Aristotele condivide con Platone l’idea che la conoscenza richieda forma ed essenza. Critica la separazione: un modello esterno non spiega il movimento e la generazione dell’individuo. La forma deve essere causa interna della sostanza.","Il confronto non elimina tutti i problemi. Come si individua una forma universale in molti individui? Qual è il rapporto tra forma della specie e organizzazione concreta? Le interpretazioni aristoteliche divergono. La risposta fondamentale resta però chiara: la realtà primaria non è una copia impoverita, ma la sostanza concreta in cui materia e forma sono unite."],"box":{"type":"worksBox","title":"Testi da collegare","text":"Categorie 1-5 per sostanza prima e seconda; Fisica I per soggetto e mutamento; Metafisica VII-IX per sostanza, essenza, forma, materia, potenza e atto; De anima II per l’applicazione dell’ilemorfismo al vivente."}}
],
"summary":["L’essere si dice in molti modi, ordinati rispetto alla sostanza.","Le sostanze prime sono individui concreti; specie e generi esprimono che cosa essi sono.","Gli enti sensibili sono unità di materia e forma.","La forma è principio organizzativo, essenza e causa, non semplice sagoma.","La distinzione tra sostanza e accidente spiega permanenza e mutamento.","Aristotele conserva la forma platonica ma la rende immanente alla cosa concreta."],
"questions":["Quali proprietà di una persona sono essenziali e quali accidentali?","La materia può esistere senza forma?","Perché l’individuo è primario nell’essere ma l’universale è centrale nella scienza?","La forma aristotelica è compatibile con la biologia contemporanea?","Aristotele supera davvero il problema platonico della partecipazione?"]
},
{
"id":"a5","n":"A5","who":"aristotele","title":"Le quattro cause","subtitle":"Una teoria plurale della spiegazione","problem":"Per comprendere una cosa basta conoscere l’evento che l’ha prodotta, oppure occorre rispondere a differenti tipi di perché?",
"sections":[
{"h":"Conoscere significa conoscere la causa","p":["Aristotele afferma che riteniamo di conoscere una cosa quando ne conosciamo il perché. La parola causa, aitia, ha un’estensione più ampia della causa efficiente moderna. Una spiegazione completa può richiedere materia, forma, origine del mutamento e fine.","Le quattro cause non sono necessariamente quattro eventi separati. Sono quattro dimensioni esplicative. In un organismo la forma e il fine possono coincidere: la struttura adulta è il compimento verso cui tende lo sviluppo."],"box":{"type":"focusBox","title":"Quattro domande","text":"Di che cosa è fatto? Che cos’è? Da che cosa proviene il mutamento? In vista di che cosa si realizza?"}},
{"h":"La causa materiale","p":["La causa materiale è ciò di cui una cosa è fatta: il bronzo della statua, il legno del tavolo, i tessuti di un organismo. Conoscere il materiale permette di comprendere possibilità e limiti. Il bronzo può essere fuso e modellato in modi che la pietra non consente.","La materia da sola non spiega l’ente. Un mucchio di mattoni e una casa possono condividere gli stessi materiali, ma differiscono per organizzazione. Una spiegazione puramente materiale rischia di non dire che cosa rende quelle parti un’unità." ]},
{"h":"La causa formale","p":["La causa formale è la struttura o essenza. Nel caso di una figura geometrica è la definizione; in un organismo è il principio organizzativo delle parti e delle funzioni. La forma risponde alla domanda che cos’è.","Essa non è soltanto un disegno esterno. La disposizione degli organi e la loro attività appartengono alla forma del vivente. Per questo la biologia aristotelica è funzionale: una parte viene compresa attraverso il lavoro che svolge nell’intero." ]},
{"h":"La causa efficiente","p":["La causa efficiente è il principio da cui parte il cambiamento: lo scultore rispetto alla statua, il padre rispetto al figlio, il medico rispetto alla guarigione in quanto esercita l’arte medica. È il significato più vicino alla causa nel linguaggio moderno.","Anche qui la spiegazione non si riduce all’ultimo urto. L’agente opera secondo una forma: lo scultore possiede il progetto, il medico la conoscenza della salute. La causa efficiente è inserita in una rete di forma e fine." ]},
{"h":"La causa finale","p":["La causa finale è ciò in vista di cui un processo avviene. Una casa viene costruita per abitare; l’arte medica opera in vista della salute; gli organi vengono spiegati attraverso la funzione che realizzano. Il fine non deve sempre essere una intenzione cosciente.","Nella natura Aristotele osserva regolarità orientate: i denti anteriori tagliano e quelli posteriori triturano. Rifiuta che tali strutture siano soltanto coincidenze fortunate. La teleologia naturale interpreta lo sviluppo come orientato verso la realizzazione della forma dell’organismo."],"box":{"type":"criticalBox","title":"Fine non significa progetto esterno","text":"Aristotele non immagina necessariamente un artefice che progetti ogni organismo. Il principio del fine è interno alla natura dell’ente, anche se la sua cosmologia culmina nel primo motore."}},
{"h":"L’esempio della statua e quello del vivente","p":["Per una statua possiamo indicare bronzo, figura, scultore e funzione commemorativa. L’esempio è utile, ma gli artefatti hanno il principio del cambiamento principalmente fuori di sé. Gli enti naturali possiedono invece un principio interno di sviluppo.","Nel vivente la forma è trasmessa nel processo generativo, l’organismo è agente del proprio sviluppo e la maturità costituisce il fine. Le cause si intrecciano molto più strettamente che nell’artefatto. La teoria delle quattro cause trova la sua espressione più forte nella biologia."],"table":{"head":["Causa","Statua","Quercia"],"rows":[["Materiale","Bronzo","Tessuti e materia organica"],["Formale","Figura rappresentata","Forma della quercia"],["Efficiente","Scultore","Pianta generatrice e processi vitali"],["Finale","Commemorare o decorare","Maturità e attività proprie della specie"]]}},
{"h":"Eredità e limiti","p":["La scienza moderna ha privilegiato cause efficienti, meccanismi e leggi matematiche, criticando la teleologia quando veniva usata come spiegazione facile. Dire che un organo esiste per una funzione non sostituisce l’analisi del processo evolutivo e dello sviluppo.","Tuttavia le domande funzionali restano presenti in biologia, ingegneria e scienze sociali. La distinzione aristotelica ricorda che spiegazioni differenti possono essere complementari. Conoscere la composizione chimica di un libro non spiega il suo argomento; conoscere l’intenzione dell’autore non spiega ogni effetto storico. La pluralità dei perché continua a essere filosoficamente utile."],"box":{"type":"worksBox","title":"Testi da collegare","text":"Fisica II per le quattro cause e la natura; Metafisica I per la storia delle cause; Parti degli animali I per funzione e spiegazione biologica; Generazione degli animali per forma e sviluppo."}}
],
"summary":["La causa aristotelica è una risposta al perché, non soltanto un evento precedente.","La causa materiale indica ciò di cui una cosa è fatta.","La causa formale esprime struttura ed essenza.","La causa efficiente è il principio del cambiamento.","La causa finale è il fine o compimento del processo.","Negli organismi forma, agente e fine sono spesso strettamente collegati.","Le quattro cause suggeriscono una pluralità di livelli esplicativi ancora utile."],
"questions":["Una spiegazione materiale può essere completa?","Qual è la differenza tra fine e intenzione cosciente?","La teoria evolutiva elimina ogni spiegazione funzionale?","Le quattro cause possono essere applicate a un’istituzione politica?","Quali cause servono per spiegare un’opera d’arte?"]
},
{
"id":"a6","n":"A6","who":"aristotele","title":"Potenza e atto","subtitle":"Il divenire come realizzazione di possibilità determinate","problem":"Come può una cosa diventare ciò che non è ancora senza che il cambiamento sia un passaggio inspiegabile dal nulla all’essere?",
"sections":[
{"h":"Il problema ereditato dai predecessori","p":["Parmenide aveva reso difficile pensare il divenire: ciò che non è non può essere pensato né generare qualcosa; ciò che è non dovrebbe diventare altro. Eraclito aveva sottolineato la struttura mutevole del mondo. Platone aveva distinto modelli intelligibili e cose sensibili.","Aristotele risponde distinguendo modi dell’essere. Una cosa può non essere in atto e tuttavia essere in potenza. Il non essere del seme rispetto alla quercia non è nulla assoluto: è una possibilità reale fondata nella sua natura."],"box":{"type":"focusBox","title":"Possibilità reale","text":"La potenza non è la semplice immaginabilità. Un seme di quercia può diventare quercia; non può diventare delfino. Le possibilità appartengono alla struttura dell’ente."}},
{"h":"Dynamis: potenza e capacità","p":["Dynamis indica il principio di cambiamento e la capacità di essere altrimenti. Il costruttore possiede la capacità di edificare; il materiale è capace di assumere una forma; un bambino può diventare adulto.","Aristotele distingue potenze attive e passive, razionali e irrazionali. Una tecnica razionale può produrre effetti contrari, come il medico può curare o danneggiare; una potenza naturale opera secondo una direzione determinata quando le condizioni sono presenti." ]},
{"h":"Energeia ed entelecheia","p":["Energeia indica l’essere in atto, l’esercizio o attività; entelecheia il compimento, l’avere il fine in sé. Vedere è atto della capacità visiva, costruire è esercizio della tecnica, la casa finita è compimento della costruzione.","Aristotele distingue attività che hanno il fine fuori di sé, come costruire una casa, e attività il cui fine è nell’esercizio stesso, come vedere o vivere bene. Questa distinzione sarà importante nell’etica: la felicità non è un prodotto separato dalla vita virtuosa, ma l’attività stessa." ]},
{"h":"Il movimento come atto dell’essere in potenza","p":["La definizione del movimento è volutamente complessa: atto di ciò che è in potenza, in quanto tale. Durante la costruzione, i materiali sono in processo di diventare casa; il movimento non è né pura potenza inattiva né atto compiuto.","Il processo esiste finché la possibilità viene realizzata. Quando la casa è terminata, la costruzione cessa. La definizione evita di trattare il movimento come una cosa aggiunta: è la condizione intermedia e reale del divenire."],"table":{"head":["Condizione","Esempio"],"rows":[["Potenza","Chi conosce la musica ma non sta suonando"],["Attualizzazione","Il musicista mentre suona"],["Atto compiuto","La capacità pienamente esercitata nell’attività"],["Privazione","Chi non possiede ancora la capacità necessaria"]]}},
{"h":"Priorità dell’atto","p":["Sebbene nel singolo sviluppo la potenza sembri venire prima — il bambino prima dell’adulto — Aristotele sostiene che l’atto è prioritario per definizione, conoscenza e in un senso per il tempo. Sappiamo che cosa sia una potenza attraverso l’atto cui è orientata.","Inoltre una realtà attuale deve precedere la generazione: un uomo in atto genera un uomo che è inizialmente in potenza. La catena rinvia a forme attuali. La priorità culmina nel primo motore come atto puro, privo di potenzialità e quindi immutabile." ]},
{"h":"Potenza, contingenza e scelta","p":["La potenza permette anche di pensare ciò che può essere e non essere. Nelle azioni umane non tutto è necessario. La deliberazione riguarda mezzi e situazioni contingenti, in cui più esiti sono realmente possibili.","Una potenza razionale richiede desiderio e decisione per passare all’atto. Sapere come agire non determina automaticamente l’azione. In questo modo la metafisica di potenza e atto si collega all’etica della scelta."],"box":{"type":"criticalBox","title":"Potenza non è destino","text":"Dire che un bambino è musicista in potenza non significa che diventerà necessariamente musicista. Servono condizioni, esercizio, educazione e scelta."}},
{"h":"Applicazioni e confronto con Platone","p":["Potenza e atto consentono ad Aristotele di spiegare il divenire dall’interno dell’ente. La quercia non imita soltanto un modello separato: la sua forma è il compimento di capacità presenti nel processo naturale.","Platone cerca stabilità oltre il cambiamento; Aristotele individua una struttura intelligibile del cambiamento stesso. La forma rimane principio, ma è causa e fine immanente. Questo passaggio è uno dei nuclei più importanti della metafisica occidentale."],"box":{"type":"worksBox","title":"Testi da collegare","text":"Fisica III per la definizione del movimento; Metafisica IX per potenza e atto; De anima II per anima come atto primo; Etica Nicomachea I e X per felicità come attività."}}
],
"summary":["Potenza e atto sono modi dell’essere che rendono intelligibile il cambiamento.","La potenza è possibilità reale e determinata, non semplice immaginazione.","L’atto è esercizio o compimento di una capacità.","Il movimento è l’attualizzazione incompiuta di ciò che è in potenza.","L’atto è prioritario perché definisce e rende conoscibile la potenza.","Le potenze razionali richiedono desiderio e scelta.","La teoria spiega il divenire senza separare la forma dalle cose."],
"questions":["Qual è la differenza tra possibile e possibile per questa cosa?","Perché l’atto è prioritario se il bambino viene prima dell’adulto?","Un talento non esercitato è una potenza reale?","Come si collega potenza e atto alla libertà?","La tecnologia crea nuove potenze umane o attualizza potenze precedenti?"]
},
{
"id":"a7","n":"A7","who":"aristotele","title":"Fisica e cosmo","subtitle":"Natura, movimento, tempo e primo motore","problem":"Come può il mondo naturale essere in continuo movimento senza dipendere da una catena infinita di motori mossi?",
"sections":[
{"h":"Physis: il principio interno","p":["Gli enti naturali possiedono in sé un principio di movimento e quiete. Una pianta cresce attraverso la propria organizzazione; una pietra cade secondo la natura attribuitale dalla fisica antica. Gli artefatti, invece, dipendono principalmente da un principio esterno in quanto artefatti.","La distinzione non significa che la natura agisca senza condizioni esterne. Acqua, nutrimento e ambiente sono necessari alla pianta. Il punto è che il modo di utilizzare tali condizioni dipende dalla forma del vivente."],"box":{"type":"focusBox","title":"Natura e tecnica","text":"Un letto di legno, se germogliasse, produrrebbe legno e non un altro letto: il principio naturale appartiene al materiale vivente, non alla forma artificiale imposta dall’artigiano."}},
{"h":"Tipi di mutamento","p":["Aristotele distingue generazione e corruzione sostanziale, alterazione qualitativa, aumento e diminuzione quantitativa, movimento locale. Non ogni cambiamento è dello stesso tipo.","Ogni mutamento richiede un soggetto, una forma acquisita e una privazione precedente. Il bronzo diventa statua: il bronzo permane, la forma viene acquisita, la mancanza di quella forma viene superata. Potenza e atto ordinano questa struttura." ]},
{"h":"Luogo, vuoto e infinito","p":["Il luogo è il limite immobile del corpo contenente, non uno spazio vuoto indipendente. Aristotele nega l’esistenza del vuoto perché ritiene che renderebbe incomprensibile la velocità e il movimento naturale.","Distingue infinito potenziale e infinito attuale. Una grandezza può essere divisa senza fine e i numeri possono essere sempre aumentati, ma non esiste per lui un corpo infinito compiuto. La distinzione consente di accettare processi indefiniti senza postulare un infinito realizzato nella natura." ]},
{"h":"Il tempo","p":["Il tempo è numero del movimento secondo il prima e il poi. Non coincide con il movimento, perché movimenti diversi possono essere misurati dallo stesso tempo, ma dipende dal mutamento e da un’anima capace di numerare.","La definizione apre una difficoltà: esisterebbe tempo senza anima? Aristotele oscilla tra il movimento numerabile e l’atto effettivo del numerare. Il problema anticipa discussioni sulla relazione tra tempo fisico e esperienza temporale."],"box":{"type":"criticalBox","title":"La fisica aristotelica è storica","text":"Molte tesi su luogo, caduta e cosmo sono state superate. Il loro valore filosofico sta nel tentativo sistematico di definire movimento, tempo, infinito e causalità, non nell’essere adottate come scienza attuale."}},
{"h":"Il cosmo finito e geocentrico","p":["Il cosmo aristotelico è sferico, finito e geocentrico. La regione sublunare è composta dai quattro elementi ed è sede di generazione e corruzione; i cieli sono associati a un quinto elemento e a movimenti circolari regolari.","Questa cosmologia verrà integrata nell’astronomia tolemaica e dominerà a lungo, ma non coincide in ogni dettaglio con il sistema di Tolomeo. La rivoluzione scientifica moderna criticherà la separazione tra fisica terrestre e celeste e la centralità della Terra." ]},
{"h":"Il primo motore immobile","p":["Se tutto ciò che è mosso è mosso da altro, una serie infinita di motori attuali non spiegherebbe il movimento presente. Aristotele introduce un principio immobile, atto puro, privo di materia e potenza.","Il primo motore non spinge il cosmo come una mano. Muove come oggetto di desiderio e pensiero: causa finale dell’ordine del movimento. La sua attività è pensiero di pensiero, contemplazione perfetta di se stesso. Il rapporto preciso tra questo principio e i motori celesti è uno dei punti più discussi della Metafisica."],"sub":[{"h":"Dio aristotelico e creazione","p":["Il primo motore non crea il mondo nel tempo. Il cosmo e il movimento sono eterni. La successiva filosofia e teologia monoteista rielaboreranno profondamente il concetto aristotelico per collegarlo a un Dio creatore e provvidente."]}]},
{"h":"Teleologia e ordine naturale","p":["La natura agisce per lo più in vista di fini. Pioggia e materia possono produrre eventi casuali, ma la regolarità degli organismi richiede secondo Aristotele una spiegazione finalistica.","La teleologia non elimina necessità materiale e caso. Le cause operano insieme. Il limite storico consiste nel non disporre dell’evoluzione per selezione naturale, capace di spiegare l’apparente finalità attraverso processi non intenzionali. La domanda aristotelica sulla funzione, però, rimane centrale nella comprensione degli organismi."],"box":{"type":"worksBox","title":"Testi da collegare","text":"Fisica II-IV per natura, cause, luogo, vuoto, infinito e tempo; De caelo per il cosmo; Metafisica XII per il primo motore; Parti degli animali per teleologia biologica."}}
],
"summary":["La natura è principio interno di movimento e quiete.","Aristotele distingue differenti tipi di mutamento.","Il tempo misura il movimento secondo prima e poi.","L’infinito naturale è potenziale, non un corpo attuale infinito.","Il cosmo aristotelico è finito, geocentrico ed eterno.","Il primo motore è atto puro e muove come causa finale.","La teleologia naturale convive con materia, necessità e caso."],
"questions":["Che cosa distingue un organismo da un artefatto?","Il tempo dipende dalla coscienza?","Perché una catena infinita di cause non soddisfa Aristotele?","Una funzione biologica richiede un fine intenzionale?","Quali parti della fisica aristotelica restano filosoficamente utili dopo Galileo?"]
},
{
"id":"a8","n":"A8","who":"aristotele","title":"Anima e conoscenza","subtitle":"Il vivente come unità di corpo, funzioni e intelletto","problem":"L’anima è una cosa contenuta nel corpo oppure il principio per cui un corpo è vivo e capace di conoscere?",
"sections":[
{"h":"L’anima come forma del vivente","p":["Nel De anima Aristotele definisce l’anima atto primo di un corpo naturale organico che ha la vita in potenza. Il corpo non è un cadavere cui si aggiunge un ospite invisibile: è corpo vivente proprio in virtù dell’anima.","L’esempio dell’occhio chiarisce il rapporto. Se l’occhio fosse un animale, la vista sarebbe la sua anima; un occhio privo della capacità di vedere è occhio soltanto per omonimia, come un occhio scolpito. La funzione appartiene all’essenza dell’organo."],"box":{"type":"focusBox","title":"Unità ilemorfica","text":"Corpo e anima sono materia e forma del vivente. Chiedere se siano uno è simile a chiedere se cera e impronta siano una cosa sola."}},
{"h":"Le facoltà dell’anima","p":["Aristotele distingue facoltà nutritiva, sensitiva, desiderativa, locomotoria e intellettiva. Le piante possiedono nutrizione, crescita e riproduzione; gli animali aggiungono percezione e desiderio; alcuni hanno movimento locale; l’uomo possiede ragione.","Le facoltà formano una gerarchia inclusiva. Chi possiede percezione possiede anche nutrizione, ma non viceversa. Non sono anime separate sovrapposte: sono livelli funzionali dell’unità vivente."],"table":{"head":["Facoltà","Attività","Viventi"],"rows":[["Nutritiva","Nutrizione, crescita, riproduzione","Piante, animali, uomini"],["Sensitiva","Percezione","Animali e uomini"],["Desiderativa","Tendenza verso piacevole o doloroso","Animali e uomini"],["Locomotoria","Movimento locale","Molti animali"],["Razionale","Pensiero e deliberazione","Uomo"]]}},
{"h":"La percezione","p":["Percepire significa ricevere la forma sensibile senza la materia, come la cera riceve l’impronta dell’anello senza ricevere l’oro. L’occhio diventa in atto il colore percepito secondo una modalità intenzionale, non materiale.","Ogni senso possiede un oggetto proprio, ma vi sono sensibili comuni come movimento, grandezza e numero. Il senso comune coordina le percezioni e consente di percepire che si percepisce. Aristotele costruisce così una psicologia funzionale complessa senza separare la percezione dal corpo." ]},
{"h":"Immaginazione, memoria ed esperienza","p":["La phantasia produce e conserva immagini anche in assenza dell’oggetto. Non coincide con percezione, perché può essere falsa e compare nei sogni; non coincide con opinione, perché anche animali privi di giudizio complesso possiedono immagini.","Le immagini rendono possibile memoria, desiderio e pensiero umano. L’intelletto non pensa senza immagini, pur cogliendo forme universali. La conoscenza razionale non salta l’esperienza sensibile, ma la rielabora." ]},
{"h":"Intelletto potenziale e intelletto agente","p":["Il libro III del De anima distingue un intelletto che può diventare tutte le cose intelligibili e un intelletto che le rende tutte attuali, paragonato alla luce. Il testo è breve e oscuro e ha generato interpretazioni divergenti.","L’intelletto agente viene descritto come separabile, impassibile e non mescolato. Non è chiaro se sia una facoltà individuale, un principio comune o una sostanza separata. Alessandro di Afrodisia, Averroè, Tommaso d’Aquino e molti altri costruiranno letture differenti. Non bisogna presentare una soluzione controversa come ovvia."],"box":{"type":"criticalBox","title":"Un problema aperto","text":"Il rapporto tra intelletto agente, individuo e immortalità è uno dei punti più difficili dell’aristotelismo. Il De anima non offre una teoria semplice dell’anima personale immortale equivalente a quella platonica."}},
{"h":"Dai sensi all’universale","p":["L’intelletto è in potenza gli intelligibili e li attualizza cogliendo la forma presente nei particolari. Conoscere uomo non significa ricordare un’Idea contemplata prima della nascita, ma astrarre e comprendere la struttura comune attraverso l’esperienza.","L’astrazione non è una fotografia mentale. Il pensiero separa nell’atto conoscitivo ciò che nella realtà concreta è unito alla materia. La forma universale diventa conoscibile senza essere una sostanza separata." ]},
{"h":"Confronto con Platone e attualità","p":["Platone tende a pensare l’anima come principio capace di esistere separatamente e la conoscenza come reminiscenza. Aristotele definisce l’anima attraverso le funzioni del corpo vivente e la conoscenza come percorso dai sensi all’universale.","La teoria aristotelica interessa ancora il dibattito sulla mente incarnata: pensiero, percezione e azione appartengono a un organismo, non a una coscienza isolata. Restano però problemi sulla soggettività, sull’intelletto e sulla sopravvivenza personale che il testo non risolve in modo univoco."],"box":{"type":"worksBox","title":"Testi da collegare","text":"De anima II per definizione e facoltà; De anima III per immaginazione e intelletto; Parva naturalia per memoria, sonno e sensazione; Analitici secondi II 19 per il passaggio da percezione a universale."}}
],
"summary":["L’anima è la forma e l’atto primo del corpo vivente.","Le facoltà sono livelli funzionali inclusi in una stessa unità organica.","La percezione riceve la forma sensibile senza la materia.","Immaginazione e memoria collegano percezione, desiderio e pensiero.","La distinzione tra intelletto potenziale e agente è interpretativamente problematica.","La conoscenza comincia dai sensi e coglie l’universale nei particolari.","Aristotele propone una concezione incarnata della vita psichica."],
"questions":["Un corpo privo di vita è ancora lo stesso corpo?","Che cosa significa ricevere una forma senza materia?","Si può pensare senza immagini?","L’intelletto agente appartiene all’individuo?","Quali somiglianze esistono tra Aristotele e le teorie contemporanee della mente incarnata?"]
},
{
"id":"a9","n":"A9","who":"aristotele","title":"Etica e felicità","subtitle":"Virtù, abitudine, scelta e saggezza pratica","problem":"Una vita buona dipende da emozioni fortunate, da regole corrette o da un carattere formato attraverso azioni e scelte?",
"sections":[
{"h":"Ogni azione tende a un bene","p":["L’Etica Nicomachea si apre osservando che arti, ricerche, azioni e scelte tendono a qualche bene. Molti fini sono subordinati ad altri: costruiamo strumenti per usarli, studiamo strategie per vincere. Deve esistere un fine scelto per se stesso che ordini gli altri.","Questo fine è eudaimonia, felicità o fioritura umana. Non coincide con un sentimento momentaneo. È il vivere e agire bene nell’arco di una vita compiuta. La traduzione felicità può ingannare se viene ridotta a soddisfazione soggettiva."],"box":{"type":"focusBox","title":"Eudaimonia","text":"La felicità aristotelica è un modo di vivere attivamente e riuscito, non una cosa posseduta né una sensazione permanente."}},
{"h":"La funzione dell’uomo","p":["Per determinare il bene umano Aristotele usa l’argomento della funzione. Il nutrirsi appartiene anche alle piante, il percepire agli animali; l’attività specificamente umana è quella dell’anima secondo ragione o non senza ragione.","Il bene umano è dunque attività dell’anima secondo virtù e, se le virtù sono più d’una, secondo la migliore e più completa. La definizione unisce capacità e esercizio: possedere una virtù senza agire non basta, come un atleta addormentato non vince una gara." ]},
{"h":"Virtù etiche e abitudine","p":["Le virtù del carattere non nascono complete per natura. Siamo naturalmente capaci di acquisirle, ma diventiamo giusti compiendo azioni giuste, coraggiosi affrontando bene la paura, temperanti regolando i piaceri. L’abitudine, ethos, forma una disposizione stabile, hexis.","Non si tratta di addestramento meccanico. Le azioni pienamente virtuose devono essere compiute con conoscenza, scelta e carattere stabile. All’inizio l’educazione e le leggi guidano; progressivamente la persona prova piacere in ciò che è nobile." ]},
{"h":"Il giusto mezzo","p":["La virtù etica è un mezzo relativo a noi tra eccesso e difetto, determinato dalla ragione come sceglierebbe la persona saggia. Il coraggio sta tra temerarietà e viltà; la generosità tra prodigalità e avarizia.","Il mezzo non è una media matematica né moderazione universale. Dipende da persona, situazione, oggetto, tempo e modo. Alcune azioni, come l’omicidio ingiusto, non diventano buone in quantità moderata. La dottrina richiede giudizio, non applicazione automatica."],"table":{"head":["Difetto","Virtù","Eccesso"],"rows":[["Viltà","Coraggio","Temerarietà"],["Insensibilità","Temperanza","Intemperanza"],["Avarizia","Generosità","Prodigalità"],["Mancanza di ambizione","Giusta ambizione","Ambizione smisurata"]]}},
{"h":"Scelta, deliberazione e responsabilità","p":["Aristotele distingue azioni volontarie, involontarie e miste. Un’azione compiuta per ignoranza può essere involontaria se produce rammarico; un’azione sotto minaccia può restare scelta in circostanze difficili.","La prohairesis, scelta deliberata, riguarda mezzi che dipendono da noi. Non deliberiamo sul fine ultimo in ogni momento, ma su come realizzarlo. Il carattere influenza ciò che appare bene, ma si forma attraverso azioni di cui siamo progressivamente responsabili." ]},
{"h":"Phronesis: la saggezza pratica","p":["La phronesis è la virtù intellettuale che permette di deliberare bene sulla vita umana. Conosce principi generali, ma anche particolari, perché l’azione riguarda sempre una situazione concreta.","Non è semplice astuzia. Una persona può essere abile nel trovare mezzi per un fine cattivo; la saggezza pratica richiede virtù morale, che rende giusto il fine. Virtù etica e phronesis si sostengono reciprocamente."],"box":{"type":"criticalBox","title":"Regole e giudizio","text":"L’etica aristotelica non offre un algoritmo. La persona saggia è criterio vivente, ma ciò solleva la domanda su come riconoscerla e correggere tradizioni ingiuste."}},
{"h":"Amicizia, piacere e vita contemplativa","p":["L’amicizia occupa due libri dell’Etica. Vi sono amicizie di utilità, piacere e virtù. L’amicizia perfetta unisce persone buone che desiderano reciprocamente il bene dell’altro. La polis stessa dipende da forme di amicizia e concordia.","Il piacere completa l’attività come bellezza che sopraggiunge alla giovinezza: non ogni piacere è buono, ma l’attività buona possiede un piacere proprio. Nel libro X la contemplazione viene presentata come attività più alta, autosufficiente e continua. Resta una tensione tra vita contemplativa e vita politica virtuosa, entrambe essenziali nell’opera."],"box":{"type":"worksBox","title":"Testi da collegare","text":"Etica Nicomachea I per felicità e funzione; II-III per virtù, mezzo e responsabilità; VI per phronesis; VIII-IX per amicizia; X per piacere e contemplazione."}}
],
"summary":["La felicità è attività compiuta dell’anima secondo virtù.","La funzione specifica umana implica ragione e attività, non semplice possesso.","Le virtù etiche si formano attraverso abitudine e scelta.","Il giusto mezzo è relativo alla situazione e determinato dalla ragione pratica.","La phronesis unisce principi e conoscenza del caso concreto.","Amicizia e istituzioni sono condizioni della vita buona.","La contemplazione è presentata come attività più alta, ma resta in tensione con la vita politica."],
"questions":["Una persona può essere felice senza beni esterni?","L’abitudine limita o costruisce la libertà?","Come si distingue il giusto mezzo dalla mediocrità?","È possibile insegnare la phronesis?","La vita contemplativa è superiore alla vita politica o ne dipende?"]
},
{
"id":"a10","n":"A10","who":"aristotele","title":"Politica, retorica e poetica","subtitle":"La vita comune e le forme pubbliche della parola e della rappresentazione","problem":"Come possono istituzioni, discorsi e opere poetiche contribuire alla vita buona senza trasformarsi in strumenti di dominio o illusione?",
"sections":[
{"h":"L’uomo animale politico","p":["La Politica continua l’Etica: il bene della persona richiede la comunità. L’uomo è zoon politikon perché possiede logos, capacità di discutere utile e dannoso, giusto e ingiusto. La polis non è soltanto alleanza per sopravvivere; esiste in vista del vivere bene.","Famiglia e villaggio precedono la città nello sviluppo, ma la polis è anteriore per natura come il tutto alle parti, perché rende possibile il pieno esercizio delle capacità umane. L’individuo isolato non è autosufficiente né moralmente completo."],"box":{"type":"focusBox","title":"Etica e politica","text":"La virtù personale dipende da educazione, leggi e istituzioni. La politica non è una tecnica esterna alla morale, ma il quadro della vita buona comune."}},
{"h":"Cittadino e costituzione","p":["Il cittadino viene definito attraverso la partecipazione alle funzioni deliberative e giudiziarie, ma la definizione varia secondo la costituzione. La polis non è soltanto territorio o popolazione: è un ordine di cariche e fini.","La politeia è la struttura che distribuisce il potere e stabilisce quale gruppo governa in vista di quale interesse. Una costituzione può cambiare anche se abitanti e mura restano gli stessi, perché cambia l’identità politica della comunità." ]},
{"h":"Forme rette e deviate","p":["Aristotele classifica i regimi secondo il numero dei governanti e il fine. Monarchia, aristocrazia e politeia governano in vista del bene comune; tirannide, oligarchia e democrazia estrema in vista dell’interesse rispettivamente di uno, dei ricchi o dei poveri.","La terminologia democrazia è diversa dall’uso moderno e non indica semplicemente ogni governo rappresentativo. Aristotele cerca spesso una costituzione mista e una classe media forte, capaci di limitare il conflitto tra ricchi e poveri."],"table":{"head":["Numero","Forma retta","Deviazione"],"rows":[["Uno","Monarchia","Tirannide"],["Pochi","Aristocrazia","Oligarchia"],["Molti","Politeia","Democrazia orientata all’interesse di parte"]]}},
{"h":"Il realismo politico","p":["A differenza della Repubblica platonica, la Politica confronta costituzioni, cause di rivoluzione e condizioni sociali. Aristotele distingue la costituzione migliore in assoluto da quella migliore possibile per una determinata città.","Questo realismo non elimina la norma. Il fine resta la vita buona e la virtù, ma il legislatore deve conoscere materiali umani, ricchezza, territorio e abitudini. La buona politica media tra ideale e possibile senza ridurre il bene all’esistente."],"box":{"type":"criticalBox","title":"Limiti storici","text":"Aristotele difende la schiavitù naturale e assegna ruoli subordinati alle donne. Queste tesi non sono dettagli accidentali: mostrano come osservazione e teleologia possano trasformare gerarchie storiche in presunte differenze naturali."}},
{"h":"La retorica come tecnica","p":["La Retorica definisce la capacità di individuare in ogni caso i mezzi disponibili di persuasione. Non è puro inganno. Nelle assemblee e nei tribunali non sempre è possibile una dimostrazione scientifica; occorre ragionare su eventi contingenti davanti a pubblici concreti.","Le prove persuasive dipendono da logos, ethos e pathos: argomento, carattere dell’oratore e disposizione emotiva dell’uditorio. Aristotele analizza le emozioni non per escluderle, ma per comprendere come influenzino il giudizio. La tecnica è moralmente ambivalente e può essere usata in modo giusto o ingiusto."],"sub":[{"h":"Entimema ed esempio","p":["L’entimema è il sillogismo retorico, spesso fondato su premesse probabili e non esplicitate; l’esempio corrisponde a una forma di induzione. La retorica traduce strutture logiche nel campo del verosimile."]}]},
{"h":"La poetica e la mimesis","p":["Per Aristotele imitare è naturale fin dall’infanzia e produce piacere perché riconoscere e apprendere sono piacevoli. La poesia non è una copia passiva. Organizza azioni secondo verosimiglianza o necessità.","La poesia può essere più filosofica della storia: la storia racconta ciò che è accaduto, la poesia ciò che potrebbe accadere secondo strutture universali. Il poeta non deve limitarsi a registrare fatti; costruisce un intreccio capace di rendere intelligibili possibilità dell’agire umano." ]},
{"h":"La tragedia","p":["La tragedia è imitazione di un’azione seria e compiuta, rappresentata da personaggi in azione. Aristotele attribuisce il primato al mythos, intreccio, rispetto ai caratteri. Una sequenza ben costruita di rovesciamento, riconoscimento e sofferenza produce l’effetto tragico.","L’eroe più efficace non è perfettamente buono né malvagio, ma cade attraverso hamartia, errore. La tragedia suscita pietà e paura e compie la catarsi di tali emozioni. Il significato di catarsi è discusso: purificazione, chiarificazione, regolazione o sollievo. Il testo non autorizza una definizione scolastica assolutamente certa."],"table":{"head":["Elemento","Funzione"],"rows":[["Mythos","Struttura delle azioni"],["Ethos","Carattere dei personaggi"],["Dianoia","Pensiero espresso"],["Lexis","Linguaggio"],["Melos","Musica"],["Opsis","Spettacolo visivo"]]}},
{"h":"Confronto con Platone","p":["Platone teme che retorica e mimesis producano apparenza di sapere e disordine emotivo. Aristotele le tratta come tecniche dotate di oggetti e regole. La persuasione è necessaria nella vita pubblica; la rappresentazione poetica può cogliere l’universale.","Il contrasto non è tra un nemico e un amante dell’arte. Entrambi studiano gli effetti educativi e politici della parola. Aristotele concede maggiore autonomia alle pratiche culturali e analizza il loro funzionamento interno, mentre Platone le giudica più direttamente dal punto di vista della verità e dell’ordine dell’anima."],"box":{"type":"worksBox","title":"Testi da collegare","text":"Politica I e III-IV per polis, cittadinanza e costituzioni; Politica V per rivoluzioni; Retorica I-II per prove e passioni; Poetica 1-18 per mimesis, intreccio, tragedia e catarsi."}}
],
"summary":["La polis esiste in vista della vita buona e completa le capacità umane.","Cittadinanza e identità politica dipendono dalla costituzione.","Le forme rette governano per il bene comune; le deviazioni per interessi di parte.","Il realismo politico aristotelico confronta ideale e condizioni concrete.","La retorica studia logos, ethos e pathos nel campo del probabile.","La poesia rappresenta possibilità universali attraverso un intreccio.","La catarsi è un concetto centrale ma interpretativamente discusso.","Platone e Aristotele divergono sul valore conoscitivo e politico della mimesis."],
"questions":["La comunità politica è necessaria per la felicità personale?","Che cosa distingue una costituzione dal semplice gruppo che governa?","È possibile persuadere senza agire sulle emozioni?","Perché la poesia può essere più universale della cronaca?","Come dobbiamo giudicare le tesi aristoteliche sulla schiavitù e sulle donne?","Che cosa potrebbe significare catarsi oggi?"]
}
];
